#!/usr/bin/env bash
# shellcheck disable=SC2329
# The library defines helpers a given wizard may not call (shellcheck SC2329), so that check is off for the file.
#
# Release signing setup (#74): makes the upload key, keeps it for local builds and CI, and points at Play Console.
# Run it from Git Bash or any bash: scripts/release-signing-setup.sh. What it sets up: wiki/workflows/release.md
# Re-run it to rotate a leaked key with a new keystore path: wiki/runbooks/leaked-signing-secret.md
# Generated by the /wizard skill (.claude/skills/wizard/SKILL.md).
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: the same in every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
# Values the wizard keeps go to a Java properties file outside the repo (LoyScan has no .env): by default the user's
# Gradle properties, which the build reads (wiki/workflows/build-and-run.md).
PROPS_FILE="${PROPS_FILE:-$HOME/.gradle/gradle.properties}"
REPO_ROOT=$(git -C "$(dirname "${BASH_SOURCE[0]}")" rev-parse --show-toplevel 2>/dev/null || pwd)
WRITTEN_PROPS=()  # keys written to PROPS_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is an action the human takes.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser: Git Bash on Windows, WSL, Linux, macOS.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N]%s ' "$YELLOW" "$1" "$RESET"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# java_path PATH: a path Java on this machine understands. Git Bash's /c/Users/… becomes C:/Users/… (forward
# slashes, since a backslash is an escape character in a properties file); elsewhere it is unchanged.
java_path() {
  if command -v cygpath >/dev/null 2>&1; then cygpath -m "$1"; else printf '%s' "$1"; fi
}

# inside_repo PATH succeeds when PATH is inside this repository's working tree. A secret there is one `git add`
# from being public, so the wizard refuses such paths.
inside_repo() {
  local dir; dir=$(dirname "$1")
  while [[ ! -d "$dir" ]]; do dir=$(dirname "$dir"); done
  local top; top=$(git -C "$dir" rev-parse --show-toplevel 2>/dev/null) || return 1
  [[ "$(cd "$top" && pwd -P)" == "$(cd "$REPO_ROOT" && pwd -P)" ]]
}

# _existing KEY: current value of property KEY in PROPS_FILE, if any (backslash escapes undone).
_existing() {
  [[ -f "$PROPS_FILE" ]] || return 1
  local line; line=$(grep -F "${1}=" "$PROPS_FILE" | grep -E "^[[:space:]]*${1//./\\.}=" | tail -n1) || return 1
  local value="${line#*=}"
  printf '%s' "${value//\\\\/\\}"
}

# ask VAR "Prompt" [PROPERTY] reads a value into $VAR. Offers PROPERTY's value in
# PROPS_FILE as a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local var="$1" prompt="$2" key="${3:-}" current="" input s=$'\001' e=$'\002' p rc=0
  [[ -n "$key" ]] && current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM${e}[Enter keeps $current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$var" '%s' "$input"
}

# ask_secret VAR "Prompt" [PROPERTY] is like ask, but input is hidden.
ask_secret() {
  local var="$1" prompt="$2" key="${3:-}" current="" input rc=0
  [[ -n "$key" ]] && current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$var" '%s' "$input"
}

# write_property KEY VALUE upserts KEY=VALUE into PROPS_FILE (replaces any existing
# line), escaping backslashes. Idempotent. Refuses a PROPS_FILE inside the repo.
# Creates the file owner-only (on Windows the folder's permissions apply instead).
write_property() {
  local key="$1" value="$2" tmp
  if inside_repo "$PROPS_FILE"; then
    SKIPPED+=("$key: $PROPS_FILE is inside the repo, so nothing was written there")
    warn "refused to write $key into $PROPS_FILE: it is inside the repo"
    return
  fi
  mkdir -p "$(dirname "$PROPS_FILE")"
  [[ -e "$PROPS_FILE" ]] || (umask 077 && : > "$PROPS_FILE")
  tmp=$(mktemp)
  grep -vE "^[[:space:]]*${key//./\\.}=" "$PROPS_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "${value//\\/\\\\}" >> "$tmp"
  cat "$tmp" > "$PROPS_FILE"
  rm -f "$tmp"
  WRITTEN_PROPS+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$PROPS_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh (value on stdin,
# never on the command line). Falls back to a warning if gh isn't ready.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | (cd "$REPO_ROOT" && gh secret set "$name") >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if (cd "$REPO_ROOT" && gh variable set "$name" --body "$value") >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Done%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_PROPS[@]} ))  && note "wrote ${#WRITTEN_PROPS[@]} value(s) to $PROPS_FILE: ${WRITTEN_PROPS[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6
KEY_ALIAS=upload

banner "LoyScan release signing"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Where the upload key lives"
say "The upload key signs every AAB you upload to Play. It is a keystore file that must"
say "never be in the repo, so pick a folder outside it, one you back up."
note "Already have one? Enter its path and the next stage only checks its password."
note "Rotating a leaked key? Enter a new path: wiki/runbooks/leaked-signing-secret.md"
while true; do
  ask KEYSTORE "Keystore path [~/.android-keys/loyscan-upload.jks]:" loyscan.upload.storeFile
  KEYSTORE="${KEYSTORE:-$HOME/.android-keys/loyscan-upload.jks}"
  KEYSTORE="${KEYSTORE/#\~/$HOME}"
  if command -v cygpath >/dev/null 2>&1; then KEYSTORE=$(cygpath -u "$KEYSTORE"); fi
  if inside_repo "$KEYSTORE"; then warn "That is inside the repo. Pick a folder outside it."; continue; fi
  break
done
(umask 077 && mkdir -p "$(dirname "$KEYSTORE")")
say "Keystore: $(java_path "$KEYSTORE")"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "The upload key and its password"
say "One password unlocks the keystore and the key (PKCS12 ignores a separate key password)."
say "Use 6 or more plain ASCII characters, no spaces at either end: Gradle reads it from a"
say "properties file. Your password manager can make one."
# The saved password is offered back only for the saved keystore: a new keystore (a rotation after a leak) must not
# get the old, possibly leaked, password by a press of Enter.
saved_password=""
saved_store=$(_existing loyscan.upload.storeFile || true)
if [[ -n "$saved_store" && "$saved_store" == "$(java_path "$KEYSTORE")" ]]; then
  saved_password=loyscan.upload.storePassword
elif [[ -n "$saved_store" ]]; then
  note "A new keystore gets a new password; the saved one isn't offered."
fi
while true; do
  ask_secret LOYSCAN_UPLOAD_STORE_PASSWORD "Password (typed blind):" "$saved_password"
  if (( ${#LOYSCAN_UPLOAD_STORE_PASSWORD} < 6 )) || [[ "$LOYSCAN_UPLOAD_STORE_PASSWORD" =~ ^[[:space:]]|[[:space:]]$ ]] \
     || LC_ALL=C grep -q '[^ -~]' <<<"$LOYSCAN_UPLOAD_STORE_PASSWORD"; then
    warn "6 or more ASCII characters, no spaces at the ends. Try again."; continue
  fi
  break
done
export LOYSCAN_UPLOAD_STORE_PASSWORD
if [[ -f "$KEYSTORE" ]]; then
  if keytool -list -keystore "$(java_path "$KEYSTORE")" -alias "$KEY_ALIAS" -storepass:env LOYSCAN_UPLOAD_STORE_PASSWORD >/dev/null 2>&1; then
    say "The keystore exists and the password opens its '$KEY_ALIAS' key."
  else
    warn "The password doesn't open the '$KEY_ALIAS' key in $KEYSTORE. Re-run and try again."
    exit 1
  fi
else
  ask CERT_NAME "Name in the key's certificate [LoyScan upload key]:"
  CERT_NAME="${CERT_NAME:-LoyScan upload key}"
  note "Only Google sees the certificate; it needn't be your real name."
  if confirm "Create the upload key now?"; then
    keytool -genkeypair -keystore "$(java_path "$KEYSTORE")" -storetype PKCS12 -alias "$KEY_ALIAS" -keyalg RSA \
      -keysize 4096 -validity 10000 -dname "CN=$CERT_NAME" -storepass:env LOYSCAN_UPLOAD_STORE_PASSWORD >/dev/null
    chmod 600 "$KEYSTORE" 2>/dev/null || true
    printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$KEYSTORE"
  else
    warn "No key, nothing else to do. Re-run when you're ready."
    exit 1
  fi
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Back it up"
say "Lose the key and Play can reset it, but releases stop until it does."
step "Copy $(java_path "$KEYSTORE") into your password manager (or another"
step "  backup you trust), together with its password and the alias '$KEY_ALIAS'."
until confirm "Backed up?"; do warn "Back it up before going on."; done

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Sign on this machine"
say "So ./gradlew bundleRelease signs here too, the build reads three Gradle properties"
say "from $PROPS_FILE, outside the repo. The password is stored there in plain text,"
say "readable by your user account."
if confirm "Write them?"; then
  write_property loyscan.upload.storeFile "$(java_path "$KEYSTORE")"
  write_property loyscan.upload.storePassword "$LOYSCAN_UPLOAD_STORE_PASSWORD"
  write_property loyscan.upload.keyAlias "$KEY_ALIAS"
else
  note "Skipped. Release builds on this machine stay unsigned; CI still signs."
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "GitHub secrets for the Release workflow"
say "The Release workflow (.github/workflows/release.yml) signs on a vX.Y.Z tag with"
say "three Actions secrets. gh sends each value over stdin; none is printed."
if confirm "Set them now?"; then
  set_secret LOYSCAN_UPLOAD_KEYSTORE_BASE64 "$(base64 -w0 "$KEYSTORE")"
  set_secret LOYSCAN_UPLOAD_STORE_PASSWORD "$LOYSCAN_UPLOAD_STORE_PASSWORD"
  set_secret LOYSCAN_UPLOAD_KEY_ALIAS "$KEY_ALIAS"
else
  SKIPPED+=("GitHub secrets: re-run this wizard, or wiki/workflows/release.md -> Once")
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Play Console"
say "Play App Signing keeps the app signing key at Google; this key only signs uploads."
open_url "https://play.google.com/console"
step "No app yet: create it. Play App Signing is on by default for a new app, and the"
step "  key that signs the first AAB you upload becomes its upload key."
step "Rotating a leaked key: request an upload key reset on the app's App signing page;"
step "  it asks for the new certificate as a PEM file."
note "Play Console's pages change; if a step doesn't match, follow Google's help:"
note "https://support.google.com/googleplay/android-developer/answer/9842756"
if confirm "Export the upload certificate (upload_certificate.pem) next to the keystore?"; then
  keytool -export -rfc -keystore "$(java_path "$KEYSTORE")" -alias "$KEY_ALIAS" \
    -file "$(java_path "$(dirname "$KEYSTORE")/upload_certificate.pem")" -storepass:env LOYSCAN_UPLOAD_STORE_PASSWORD >/dev/null 2>&1 \
    && printf '  %s✓ exported%s %s\n' "$GREEN" "$RESET" "$(dirname "$KEYSTORE")/upload_certificate.pem" \
    || SKIPPED+=("export upload_certificate.pem: keytool -export -rfc (wiki/runbooks/leaked-signing-secret.md)")
fi
pause "Done in Play Console? Press Enter"

finish
}

run_wizard "$@"; exit
